INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('dad430f4-a750-4522-a3e5-a93dd1d23752', 'Knee Thrust - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this thrusting exercise that develops speed, power, and coordination. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '58091201', '58091201-Alternating-Knee-Thrust-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Knee Thrust - Alternating', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dad46aec-d628-4202-87ec-35a5692ab7d5', 'Single Leg Hyperextension (Dumbbell)', 'Back', 'Dumbbells, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '106321201', '106321201-Dumbbell-Single-Leg-Hyperextension-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'back_extension', 'Single Leg Hyperextension', 'leg_curl, squat, leg_press, lunge', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('dada6b89-c6a0-4d6d-9ef9-78266f7d63db', 'Hip Clam', 'Legs', 'Bodyweight', '{"Glutes","Hips"}'::text[], '{"Hamstrings"}'::text[], 'The Hip Clam is a lower body movement exercise that targets your glute med/abductors. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '63101201', '63101201-Hip-Clam-(VERSION-2)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Set up in the starting position for Hip Clam. 2. Execute the movement with proper form, focusing on your glute med/abductors. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Hip Clam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dadca018-dede-4e3a-aa99-e1efbf1da67c', 'Side Step Walking', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. Your quads work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '90551201', '90551201-Side-Step-Walking-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Walking. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Side Step Walking', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('dadcf9f1-9af6-4bc7-88e5-ef897ab104ec', 'Calf Jump', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{"Glutes"}'::text[], 'The Calf Jump is an explosive exercise that combines cardiovascular training with dynamic jumping movements. Your quads, calves work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '107511201', '107511201-Calf-Jump-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Set up in the starting position for Calf Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Calf Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('dae6bba1-aeb6-4db3-986f-1cfccfd497da', 'Decline Pullover (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. Your lats, triceps work as secondary movers, adding to the training stimulus. The decline position targets the lower portion of the muscles more intensely. The dumbbell variation provides freedom of movement and greater range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '75251201', '75251201-Dumbbell-Decline-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Continue for your target rep count, maintaining good form throughout.', 'Pullover', 'Pull', NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pullover', 'Decline Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('db014681-42af-419d-82cb-3bf050f950cc', 'Down To Upward Dog', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Excellent for pre-exhausting the target muscle before compound lifts.', '46521201', '46521201-Down-to-Upward-Dog_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Set up in the starting position for Down To Upward Dog. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'yoga', 'Down To Upward Dog', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('db0c8a1f-177d-4a46-af37-7a661f8fcd33', 'Side Plank With Raised Leg (left)', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '62081201', '62081201-Side-Plank-with-Raised-Leg-(VERSION-2)-(left)-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank With Raised Leg', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('db0ef837-08da-4e8d-b9c2-59446913b39b', 'Sumo Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '81921201', '81921201-Dumbbell-Sumo-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Sumo Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Sumo Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('db1148f6-f2a0-4b31-937c-6295b04d5fdf', 'Marching in Place', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Enhance your stamina and burn calories with this effective cardio movement. You''ll also feel your hip flexors working to support the movement. Regular cardio training builds the aerobic base for better overall fitness.', '44201201', '44201201-Marching-On-Spot_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Set up in the starting position for Marching On Spot. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'marching', 'Marching On Spot', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('db234aa8-f90a-433a-b704-76b4179dd58d', 'Step Behind Rotational Throw (Medicine Ball)', 'Back', 'Medicine Ball', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Medicine Ball Step Behind Rotational Throw is an explosive exercise that combines cardiovascular training with dynamic rowing movements. The quads assist throughout the movement, making this a well-rounded exercise. Great for improving athletic performance, burning calories, and building conditioning.', '43831201', '43831201-Medicine-Ball-Step-Behind-Rotational-Throw_Plyomet.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Step Behind Rotational Throw. 2. Set up a box or step platform at the appropriate height. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'woodchop', 'Medicine Ball Step Behind Rotational Throw', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('db356ce6-5535-4f68-b936-56f3b24bb133', 'Standing Hip Extension (Bent Knee)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This extension exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '7921201', '07921201-Standing-Hip-Extension-(bent-knee)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Extend through the target joint(s) for Standing Hip Extension. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Hip Extension', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('db37a4a4-eef3-40d5-877c-638b95426322', 'Decline Bent Leg Reverse Crunch (Decline Bench)', 'Core', 'Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Decline Bent Leg Reverse Crunch, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The decline position targets the lower portion of the muscles more intensely. A strong core improves posture, protects your spine, and enhances all other lifts.', '30721201', '30721201-Decline-Bent-Leg-Reverse-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', 'Crunch', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'crunch', 'Decline Bent Leg Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('db5c62c4-c3a6-4c60-89e1-833beba95385', 'Seated Single Leg Knee Extension (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this extension exercise for quad development. Being seated provides stability, allowing you to focus on the working muscles. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '107461201', '107461201-Resistance-Band-Seated-Single-Leg-Knee-Extension-.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Secure the resistance band appropriately for Resistance Band Seated Single Leg Knee Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Single Leg Knee Extension', 'squat, leg_press, lunge', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('db8ce97c-936c-4ccb-8b3b-c4f91ac4d3ea', 'Slam (Medicine Ball)', 'Core', 'Medicine Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. A strong core improves posture, protects your spine, and enhances all other lifts.', '75351201', '75351201-Medicine-Ball-Slam-(VERSION-2)-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Slam. 2. Set up in the starting position for Medicine Ball Slam. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Medicine Ball Slam', 'squat, bench_press, deadlift', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('db90bf09-304b-4a55-8513-770acb1a9f72', 'Pronated To Neutral Grip Row (Dumbbell)', 'Back', 'Dumbbells', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '23251201', '23251201-Dumbbell-Pronated-to-Neutral-Grip-Row-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Pronated To Neutral Grip Row. 2. Use a neutral grip with palms facing each other. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'general_exercise', 'Pronated To Row - Neutral Grip', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('db9537a8-44d3-456e-a4aa-6d78df0b596b', 'Frog Crunch Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Frog Crunch Hold is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '79921201', '79921201-Frog-Crunch-Hold_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Hold the position for the prescribed time, maintaining tension. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'crunch', 'Frog Crunch Hold', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('db9c2682-0ab4-43c4-b184-c3e6e5eab1e8', 'Hip Flexor Stretch Rear Foot Elevated (Step Platform)', 'Legs', 'Step Platform', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your hip flexors area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. This is a great exercise for all fitness levels with proper scaling.', '25681201', '25681201-Hip-Flexor-Stretch-Rear-foot-elevated-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Move into the stretch position for Hip Flexor Stretch Rear Foot Elevated. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on the mind-muscle connection. Works well for hip flexors activation.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Hip Flexor Stretch Rear Foot Elevated', 'split_squat, lunge, leg_press', TRUE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dba422f9-4b44-4839-9d0e-96e25ead1eae', 'Hollow Body 45 Degrees', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts. This is a great exercise for all fitness levels with proper scaling.', '76861201', '76861201-Hollow-Body-45-degrees-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up in the starting position for Hollow Body 45 Degrees. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hollow Body 45 Degrees', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('dbc64b61-cafd-4165-82f4-f2a8e1eb1ec3', 'Crunch (arms Straight)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Crunch (arms Straight) is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '38211201', '38211201-Crunch-(arms-straight)-(male)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dbcaca84-1795-4ed9-90c9-10b548ab9b99', 'Seated Shoulder Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Seated Shoulder Stretch provides a deep stretch for your shoulders, ideal for recovery and mobility work. The upper back assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '79761201', '79761201-Seated-Shoulder-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Shoulder Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Shoulder Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dbd4bd02-3924-4079-959e-5ce3382dd12a', 'Burpee (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'The Burpee With Chair is an explosive exercise that combines cardiovascular training with dynamic movement movements. You''ll also feel your chest, quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '105081201', '105081201-Burpee-with-Chair-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Squat down and place hands on the floor, jump feet back to plank. 3. Jump feet back toward hands, then explosively jump up with arms overhead. 4. Land softly and immediately begin the next rep. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'burpee', 'Burpee With Chair', 'mountain_climber, box_jump, jumping_jack', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('dbe39663-885f-49a2-9638-910da4b9f281', 'Single Arm Chest Press (Plate Loaded)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. A well-developed chest contributes to upper body strength and aesthetics.', '57361201', '57361201-Lever-Single-Arm-Chest-Press-(plate-loaded)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Single Arm Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('dbe540b3-a619-4d36-9c15-5efdda7f11fd', 'Shrug (Dumbbell)', 'Back', 'Dumbbells', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '4061201', '04061201-Dumbbell-Shrug_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'shrug', 'Shrug', 'deadlift, bent_over_row, face_pull', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('dbe69b02-7872-4131-9461-15970a28e6b2', 'Lunge With Overhead Raise Stretch (Stick)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stick Lunge With Overhead Raise Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '54021201', '54021201-Stick-Lunge-with-Overhead-Raise-Stretch-(female)_T.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Raise the weight in the prescribed direction for Stick Lunge With Overhead Raise Stretch. 2. Lower with control, maintaining tension throughout. 3. Move into the stretch position for Stick Lunge With Overhead Raise Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'stretch_general', 'Stick Lunge With Overhead Raise Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dbe93cda-ec03-4c28-b140-6a8061d7773d', 'Palm Rotational Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '13191201', '13191201-Cable-Palm-Rotational-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Adjust the cable machine to the correct height and attachment for Cable Palm Rotational Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'woodchop', 'Palm Rotational Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('dbf5e90d-1e9a-48ac-83dd-2e1c24cf2f71', 'Quick Feet Run', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Regular cardio training builds the aerobic base for better overall fitness. This variation is excellent for building mind-muscle connection.', '61021201', '61021201-Quick-Feet-Run-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Quick Feet Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Quick Feet Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc1145ce-5b04-4ed3-9b55-1b9e2f0a8968', 'V Up (Medicine Ball) - Alternating', 'Core', 'Medicine Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. Building core stability helps with everything from heavy deadlifts to daily activities. Maintain proper breathing - exhale during the effort phase.', '69471201', '69471201-Medicine-Ball-Alternate-V-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Alternate V Up. 2. Alternate between sides/arms/legs with each repetition. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'v_up', 'Medicine Ball V Up - Alternating', 'squat, bench_press, deadlift', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc27568e-f6c6-494e-bfcb-a6f453b6c545', 'Standing Hammer Curl (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Dedicated arm training builds both strength and muscular definition.', '46191201', '46191201-Band-Standing-Hammer-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Secure the resistance band appropriately for Band Standing Hammer Curl. 2. Begin in a standing position with good posture. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'hammer_curl', 'Standing Hammer Curl', 'bicep_curl, preacher_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('dc34f7ab-cef7-4e95-a57d-eb18e0b78058', 'Side Step Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength. Start with lighter weight to master the movement pattern.', '105681201', '105681201-Side-Step-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side Step Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc377aa9-01e7-4e5b-bb38-8c564352cc70', 'Cross Side Step Lats Squeeze', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Cross Side Step Lats Squeeze is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '97901201', '97901201-Cross-Side-Step-Lats-Squeeze-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Cross Side Step Lats Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Cross Side Step Lats Squeeze', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc451f48-1296-4209-8ce5-edeb5c5b57ab', 'Kneeling Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Kneeling helps eliminate lower body momentum from the movement. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '69921201', '69921201-Cable-Kneeling-Triceps-Extension-(female)_Upper-Ar.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Triceps Extension. 2. Kneel on the floor (use a pad for comfort if needed). 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'tricep_extension', 'Kneeling Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('dc471b79-3e84-42d1-bf56-6a6a6e75fa24', 'Calf Raise On A Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Strong legs are the foundation for athletic performance and functional fitness. A staple exercise that belongs in most training programs.', '106331201', '106331201-Bodyweight-Calf-Raise-on-a-Stepbox-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up a box or step platform at the appropriate height. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Raise On A Stepbox', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dc52eb45-1fbc-4ecc-9d93-d68cf0e6cedd', 'Backward Kneeling Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Kneeling Crunch, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. The kneeling position adds a core stability challenge. The cable setup allows you to adjust the angle of resistance. Core strength is foundational for athletic performance and injury prevention.', '57411201', '57411201-Cable-Kneeling-Crunch-(VERSION-2)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Crunch. 2. Kneel on the floor (use a pad for comfort if needed). 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Kneeling Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('dc5d59de-ad58-4838-85ef-cf5083ebb5de', 'Kneeling Hold To Stand Clean Grip (Kettlebell)', 'Arms', 'Kettlebell', '{"Forearms"}'::text[], '{}'::text[], 'The Kettlebell Kneeling Hold To Stand Clean Grip is a compound movement exercise that engages your entire body. Secondary activation of your quads, glutes, traps provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. Kettlebells are excellent for building functional, real-world strength. Compound movements like this develop coordination, power, and overall fitness.', '65221201', '65221201-Kettlebell-Kneeling-Hold-to-Stand-Clean-grip_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Select an appropriately weighted kettlebell for Kettlebell Kneeling Hold To Stand Clean Grip. 2. Kneel on the floor (use a pad for comfort if needed). 3. Explosively pull the weight upward from the starting position. 4. Pull yourself under the weight and catch it at shoulder level. 5. Stand to complete the lift, then lower with control. 6. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'kneeling_hold', 'Kneeling Hold To Stand Clean Grip', 'power_clean, deadlift, front_squat', FALSE, 'kettlebell', TRUE, 3, 90, 4, 75, 88, 88, 78),
('dc6cac54-cb91-47fd-9169-efd6245b6878', 'Forward Backward Sideward', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Start with lighter weight to master the movement pattern. Consistency with this movement will yield noticeable results.', '50861201', '50861201-Forward-Backward-Sideward-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Forward Backward Sideward. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Forward Backward Sideward', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc72f646-9411-4477-992f-18438ee1d403', 'Side Step Punch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. Your shoulders work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '64781201', '64781201-Side-Step-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Punch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc7b9b0d-8819-4cbb-b014-5ab507f877f9', 'Kneeling Cross Body Lat Pulldown (Resistance Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'A challenging plyometric exercise, the Resistance Band Kneeling Cross Body Lat Pulldown ( builds reactive power and improves conditioning. Your shoulders, core work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. The band creates increasing tension as it stretches, challenging the lockout. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '83261201', '83261201-Resistance-Band-Kneeling-Cross-Body-Lat-Pulldown-(.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Secure the resistance band appropriately for Resistance Band Kneeling Cross Body Lat Pulldown (. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Kneeling Cross Body Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('dc828acc-e616-44bd-9a20-7b541f77eabf', 'Plank Row', 'Back', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Strengthen your midsection with this rowing movement that works your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '80581201', '80581201-Plank-Row-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Row', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('dc84f089-16ab-4fea-b8d6-37bb866e9fcd', 'Standing Diagonal Cross Toe Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. The hip flexors assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '80361201', '80361201-Standing-Diagonal-Cross-Toe-Touch-(female)_Plyomet.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Diagonal Cross Toe Touch. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'toe_touch', 'Standing Diagonal Cross Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dc925a8e-8798-495e-b1ac-a5ad36536196', 'Elastic Bed Jumping', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. Your quads, calves work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '99831201', '99831201-Elastic-Bed-Jumping-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Set up in the starting position for Elastic Bed Jumping. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Elastic Bed Jumping', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('dcaec047-ce07-4fc0-96d3-40ccb7ec113f', 'Seated Floor Marching With Arms Pump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. You''ll also feel your hip flexors working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Great for improving athletic performance, burning calories, and building conditioning.', '107021201', '107021201-Seated-Floor-Marching-with-Arms-Pump-(female)_Ply.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Position yourself on the floor for Seated Floor Marching With Arms Pump. 2. Sit on the floor with your legs positioned as required. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 47, 9, 8, FALSE, TRUE, 'marching', 'Seated Floor Marching With Arms Pump', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('dcdd936a-6d12-4093-80b1-319631abde9d', 'Kneeling Adductors Side Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Designed to lengthen your adductors, the Kneeling Adductors Side Stretch helps improve mobility and prevent stiffness. Your hips work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. Flexibility work like this enhances performance and prevents stiffness.', '78851201', '78851201-Kneeling-Adductors-Side-Stretch-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Adductors Side Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'lat_stretch', 'Kneeling Adductors Side Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('dcdf09d5-fd41-4281-a135-804422ff5917', 'Standing Russian Twist Knee Thrust', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Standing Russian Twist Knee Thrust builds reactive power and improves conditioning. You''ll also feel your abs working to support the movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '85101201', '85101201-Standing-Russian-Twist-Knee-Thrust-(male)_Plyometr.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Stand tall with your feet firmly planted. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Russian Twist Knee Thrust', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dcdf11db-ddf3-4b4c-aa52-b373819e171c', 'Standing Single Arm Preacher Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Standing Single Arm Preacher Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Performing this standing challenges your balance and core engagement. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '83171201', '83171201-Cable-Standing-Single-Arm-Preacher-Curl-(male)_Upp.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Single Arm Preacher Curl. 2. Stand with feet about shoulder-width apart. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'preacher_curl', 'Standing Single Arm Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('dce2adc7-f938-4d2d-aca0-6be7fa92352c', 'Triceps Extension - Forward Push (Machine)', 'Arms', 'Tricep Extension Machine', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The machine guides your movement path for safer, more controlled repetitions. Arm strength supports grip, pulling, and pushing in compound movements. Focus on controlled form throughout each repetition.', '71191201', '71191201-Lever-Triceps-Extension-(VERSION-3)-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lever Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('dce43b7a-a894-45a9-9d27-5a9f9ddc6ae5', 'Lying 6 Inch Hold', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. Focus on controlled form throughout each repetition.', '72481201', '72481201-Lying-6-Inch-Hold-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Lie down in the appropriate position for Lying 6 Inch Hold. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying 6 Inch Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('dd002dc3-5d17-4fd6-8a2b-8d12cff67511', 'Lying Row - Reverse Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band Lying Reverse Grip Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '68691201', '68691201-Band-Lying-Reverse-Grip-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Secure the resistance band appropriately for Band Lying Reverse Grip Row. 2. Lie down in the appropriate position for Band Lying Reverse Grip Row. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Row - Reverse Grip', 'Lying Row - Reverse Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('dd3e8a24-a133-4399-8207-068657fd0fcd', 'Stepback Flap', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stepback Flap is an explosive exercise that combines cardiovascular training with dynamic stepping movements. You''ll also feel your quads working to support the movement. Great for improving athletic performance, burning calories, and building conditioning.', '68541201', '68541201-Stepback-Flap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback Flap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Stepback Flap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dd5d7e58-b6aa-4253-998b-29a5c38014f0', 'Poliquin Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this stepping movement focusing on your full body. Your quads work as secondary movers, adding to the training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '96031201', '96031201-Bodyweight-Poliquin-Step-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Bodyweight Poliquin Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Poliquin Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dd657d25-d8ef-44a9-8481-96ee9e6dff80', 'Diagonal Bend Hold', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Diagonal Bend Hold is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '67621201', '67621201-Diagonal-Bend-Hold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Move into the stretch position for Diagonal Bend Hold. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Diagonal Bend Hold', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('dd73dd9d-1b45-497b-8475-403716fbb58e', 'Lying Leg Raise To Side', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Leg Raise To Side, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '32681201', '32681201-Lying-Leg-Raise-to-Side-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie on your side with your body aligned. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Leg Raise To Side', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dd83f923-855b-4a0e-b807-c21f0fa1b0d4', 'Seated Press (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Being seated provides stability, allowing you to focus on the working muscles. The kettlebell''s offset center of mass increases the stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '5461201', '05461201-Kettlebell-Seated-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Select an appropriately weighted kettlebell for Kettlebell Seated Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('dd900230-1753-417a-82ab-b974a5e1b7a8', 'Bent Leg Circle Kick (kneeling)', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Bent Leg Circle Kick (kneeling) is a lower body kicking exercise that targets your delts. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '25701201', '25701201-Bent-Leg-Circle-Kick-(kneeling)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Bent Leg Circle Kick. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Bent Leg Circle Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dd9b78f1-f87b-4212-8a59-2a488b44a2c8', 'Decline Push Up Box (Plyo Box)', 'Chest', 'Plyo Box', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. The kneeling position adds a core stability challenge. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '71021201', '71021201-Decline-Kneeling-Push-Up-on-Box-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up a box or step platform at the appropriate height. 2. Kneel on the floor (use a pad for comfort if needed). 3. Keep your body in a straight line from head to heels throughout. 4. Lower your chest toward the floor by bending your elbows. 5. Push through your palms to return to the starting position. 6. Complete all reps with control before resting.', 'Push Up', NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Decline Kneeling Push Up On Box', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('dda00369-4678-414f-8d76-7d959728bba4', 'Incline Triceps Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'The Dumbbell Incline Triceps Kickback is an arm kicking exercise targeting your glutes. You''ll also feel your hamstrings working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '78791201', '78791201-Dumbbell-Incline-Triceps-Kickback-(male)_Upper-Arm.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Triceps Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Incline Triceps Kickback', 'tricep_pushdown, tricep_extension', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('dda54248-06b3-4ad6-9ab0-5075cf2a1d34', 'Landmine Chest Press With Viking Pres - Neutral Grip (Landmine)', 'Chest', 'Landmine Attachment, Barbell', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Landmine Neutral Grip Chest Press With Viking Pres is a pressing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. A well-developed chest contributes to upper body strength and aesthetics.', '87061201', '87061201-Landmine-Neutral-Grip-Chest-Press-with-Viking-Pres.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Use a neutral grip with palms facing each other. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'bench_press', 'Landmine Chest Press With Viking Pres - Neutral Grip', 'Landmine Chest Press With Viking Pres - Neutral Grip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('ddbea38f-7700-4659-b54d-489a36880782', 'Twist Turn Lift', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Twist Turn Lift. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '75851201', '75851201-Twist-Turn-Lift-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Rotate your torso through the movement pattern for Twist Turn Lift. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist Turn Lift', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ddc77ace-4720-446e-a933-b47344b3e2e5', 'Twisting Knee Thrust - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'This dynamic twisting movement gets your heart rate up while developing explosive strength. Secondary activation of your abs provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Can be modified for beginners or progressed for advanced athletes.', '89171201', '89171201-Alternate-Twisting-Knee-Thrust-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 42, 5, 7, FALSE, TRUE, 'knee_drive', 'Twisting Knee Thrust - Alternating', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('ddd1f9eb-8b1d-4b67-8e81-5f3ffe1d8a68', 'Lying Hip Extension - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '6141201', '06141201-Lying-Alternate-Hip-Extension_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Hip Extension. 2. Extend through the target joint(s) for Lying Alternate Hip Extension. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_kickback', 'Lying Hip Extension - Alternating', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('dde4474f-eb40-4af6-b779-112444102c19', 'Ipsilateral Glute Dominant Step Up (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stepping movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '75861201', '75861201-Cable-Ipsilateral-Glute-Dominant-Step-up-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Ipsilateral Glute Dominant Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'step_up', 'Ipsilateral Glute Dominant Step Up', 'lunge, split_squat, squat', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('de01f144-21c7-4a29-b80f-c83a4907fdce', 'Seated Woodchopper (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. The seated position helps isolate the target muscles by removing momentum. Core strength is foundational for athletic performance and injury prevention.', '90961201', '90961201-Sitting-Woodchopper-on-a-Chair-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Ensure full range of motion on each rep. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 35, 9, 8, TRUE, TRUE, 'woodchop', 'Seated Woodchopper On A Chair', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('de1c8ef3-9a3b-4da6-b3a5-5e333b73ac9d', 'Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition. Maintain proper breathing - exhale during the effort phase.', '23851201', '23851201-Dumbbell-Preacher-Curl-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('de28fb42-363f-47f8-b35a-1f7673b392f9', 'Cossack Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Lower body strength improves everything from walking to heavy compound lifts. Control the negative portion for maximum muscle engagement.', '77731201', '77731201-Barbell-Cossack-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Cossack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Cossack Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
